revoke all on function public.ils_professional_security_reviewer_is_authorized(uuid) from public,anon,authenticated; grant execute on function public.ils_professional_security_reviewer_is_authorized(uuid) to service_role; create table if not exists public.ils_professional_security_reviewer_authorization_hardening_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_security_reviewer_authorization_hardening_tests enable row level security; alter table public.ils_professional_security_reviewer_authorization_hardening_tests force row level security; revoke all on public.ils_professional_security_reviewer_authorization_hardening_tests from anon,authenticated; insert into public.ils_professional_security_reviewer_authorization_hardening_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('ANON_EXECUTION','BLOCK','BLOCK',true,'Anonymous callers cannot execute reviewer authorization gate.'),('AUTHENTICATED_EXECUTION','BLOCK','BLOCK',true,'Authenticated clients cannot directly invoke the backend-only authorization gate.'),('SERVICE_ROLE_EXECUTION','ALLOW','ALLOW',true,'Backend service role retains controlled execution.'),('ACTIVE_IDENTITY','REQUIRED','REQUIRED',true,'Authorization requires active status and identity verification.'),('TRAINING','REQUIRED','REQUIRED',true,'Security training verification remains mandatory.'),('ROLE_SCOPE','SECURITY_REVIEWER_OR_ADMIN','SECURITY_REVIEWER_OR_ADMIN',true,'Only explicitly allowed reviewer roles qualify.'),('VALIDITY_WINDOW','ENFORCED','ENFORCED',true,'Start/end validity timestamps are enforced.'),('REVOKED','BLOCK','BLOCK',true,'Revoked authorization cannot approve.'),('SELF_APPROVAL','BLOCK','BLOCK',true,'Self-approval remains prohibited by review workflow.'),('CLIENT_REVIEWER','BLOCK','BLOCK',true,'Client identities are not security reviewers.'),('NO_LIVE_REVIEWERS','PASS','PASS',true,'TEST currently has no reviewer authorization records.'),('NO_PRODUCTION_TOUCH','PASS','PASS',true,'Only TEST project is modified by this action.');